package edu.bca.futsal.controller;
import edu.bca.futsal.model.Account; import edu.bca.futsal.service.FutsalService; import jakarta.servlet.http.HttpSession; import java.util.*;
import org.springframework.dao.DataAccessException; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*;
@Controller public class WebController {
 private final FutsalService service; public WebController(FutsalService service){this.service=service;}
 @ModelAttribute public void identity(HttpSession s,Model m){m.addAttribute("user",s.getAttribute("user"));}
 @GetMapping({"/","/login"}) public String loginPage(HttpSession s){return s.getAttribute("user")==null?"login":"redirect:/dashboard";}
 @PostMapping("/login") public String login(@RequestParam String email,@RequestParam String password,HttpSession s,Model m){Account a=service.login(email,password);if(a==null){m.addAttribute("error","Email or password was incorrect.");return "login";}s.setAttribute("user",a);return "redirect:/dashboard";}
 @GetMapping("/logout") public String logout(HttpSession s){s.invalidate();return "redirect:/login";}
 @GetMapping("/dashboard") public String dashboard(){return "dashboard";}
 @GetMapping("/grounds") public String grounds(@RequestParam(required=false) String date,Model m){String selected=date==null||date.isBlank()?java.time.LocalDate.now().plusDays(1).toString():date;try{java.time.LocalDate.parse(selected);}catch(java.time.DateTimeException ex){selected=java.time.LocalDate.now().plusDays(1).toString();}m.addAttribute("selectedDate",selected);m.addAttribute("slots",service.slots());m.addAttribute("grounds",service.grounds(selected));m.addAttribute("bookings",service.bookings());return "grounds";}
 @PostMapping("/bookings") public String book(@RequestParam int groundId,@RequestParam String matchDate,@RequestParam String slot,HttpSession s,Model m){Account a=(Account)s.getAttribute("user");m.addAttribute("flash",service.book(groundId,a.getId(),matchDate,slot));m.addAttribute("selectedDate",matchDate);m.addAttribute("slots",service.slots());m.addAttribute("grounds",service.grounds(matchDate));m.addAttribute("bookings",service.bookings());return "grounds";}
 @GetMapping("/matches") public String matches(HttpSession s,Model m){Account a=(Account)s.getAttribute("user");m.addAttribute("matches",service.openMatches(a.getId()));return "matches";}
 @GetMapping("/matches/{id}") public String matchDetails(@PathVariable int id,HttpSession s,Model m){Account a=(Account)s.getAttribute("user");m.addAttribute("match",service.matchDetails(id,a.getId()));return "match-details";}
 @PostMapping("/matches/{id}/join") public String join(@PathVariable int id,HttpSession s,Model m){Account a=(Account)s.getAttribute("user");m.addAttribute("flash",service.join(id,a.getId()));m.addAttribute("match",service.matchDetails(id,a.getId()));return "match-details";}
 @GetMapping("/organizer") public String organizer(HttpSession s,Model m){Account a=(Account)s.getAttribute("user");m.addAttribute("bookings",service.bookingsFor(a.getId()));m.addAttribute("matches",service.myMatches(a.getId()));m.addAttribute("requests",service.requests(a.getId()));return "organizer";}
 @PostMapping("/matches") public String createMatch(@RequestParam int bookingId,@RequestParam int needed,@RequestParam String title,@RequestParam(required=false,defaultValue="") String notes,HttpSession s,Model m){Account a=(Account)s.getAttribute("user");m.addAttribute("flash",service.createMatch(bookingId,a.getId(),needed,title,notes));m.addAttribute("bookings",service.bookingsFor(a.getId()));m.addAttribute("matches",service.myMatches(a.getId()));m.addAttribute("requests",service.requests(a.getId()));return "organizer";}
 @PostMapping("/requests/{id}/{decision}") public String decide(@PathVariable int id,@PathVariable String decision,HttpSession s,Model m){Account a=(Account)s.getAttribute("user");m.addAttribute("flash",service.decide(id,a.getId(),decision.toUpperCase(Locale.ROOT)));m.addAttribute("bookings",service.bookingsFor(a.getId()));m.addAttribute("matches",service.myMatches(a.getId()));m.addAttribute("requests",service.requests(a.getId()));return "organizer";}
 @GetMapping("/my-requests") public String myRequests(HttpSession s,Model m){Account a=(Account)s.getAttribute("user");m.addAttribute("requests",service.myRequests(a.getId()));return "my-requests";}
 @PostMapping("/requests/{id}/cancel") public String cancel(@PathVariable int id,HttpSession s,Model m){Account a=(Account)s.getAttribute("user");m.addAttribute("flash",service.cancel(id,a.getId()));m.addAttribute("requests",service.myRequests(a.getId()));return "my-requests";}
 @ExceptionHandler(DataAccessException.class) public String databaseError(Exception e,Model m){m.addAttribute("error","Database connection failed. Check MySQL is running and DB_URL, DB_USER, DB_PASSWORD are set; then import database/schema.sql.");return "error";}
}
